function expandCompactDraws(compact: CompactDrawTuple[]): Draw[] {
  return compact.map((t) => {
    const year = parseInt(t[0].slice(0, 4), 10);
    const contestNumber = t[1];
    return {
      id: `${year}-${String(contestNumber).padStart(3, '0')}`,
      contestNumber,
      year,
      date: t[0],
      numbers: [t[2], t[3], t[4], t[5], t[6], t[7]],
      jolly: t[8],
      superstar: t[9]
    };
  });
}

let cachedFullDataset: Draw[] | null = null;

export function generateFullHistoricalDataset(): Draw[] {
  if (!cachedFullDataset) {
    cachedFullDataset = expandCompactDraws(OFFICIAL_DRAWS_COMPACT);
  }
  return [...cachedFullDataset];
}

export const INITIAL_HISTORICAL_DRAWS: Draw[] = generateFullHistoricalDataset().slice(0, 50);
